const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
"rg -n \"noncomputable def seedUniv|def seedUniv|seedUniv.*LocalEquations|\\.eqns\" AlgebraicJacobian/Picard/DivSchemeSeedUniv*.lean | head -n 200",
"sed -n '1,170p' AlgebraicJacobian/Picard/DivSchemeSeedUnivFields.lean",
"rg -n \"supportLocus_subset|subset_supportLocus|mem_supportLocus|supportLocus\" AlgebraicJacobian/Picard/DivSchemeSeedUniv*.lean | head -n 240",
"rg -n \"finite_colength|Module.Finite.*quot|hcolFin\" AlgebraicJacobian/Picard/DivSchemeSeedUniv*.lean | head -n 240"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:22000})));
rs.forEach((r,i)=>text(`===${i+1}===\n${r.output}`));

const cmds=[
"rg -n \"structure Presentation|def presentationDivisor|support.*presentationDivisor|presentationDivisor.*support|mem_support.*presentation\" AlgebraicJacobian -g '*.lean' | head -n 220",
"rg -n \"pulledEquations|pullback.*LocalEquations|fibre.*LocalEquations\" AlgebraicJacobian/Picard/DivSchemeAdaptationFibreRegular.lean AlgebraicJacobian/Picard/DivSchemeFibrePointRead.lean -g '*.lean'",
"rg -n \"CurveDivisor.*support|support.*CurveDivisor|toFinsupp.*support\" AlgebraicJacobian .lake/packages 2>/dev/null | head -n 180"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:16000})));
rs.forEach((r,i)=>text(`===${i+1}===\n${r.output}`));
